  VALUES 
    (316::BIGINT, 'Es muy buen profe. Sus clases son 100% virtuales, de 1.5 horas maximo. El curso consta de 10 tareas que se resuelven con lo que se ve en clase. Super sencillo pasar con el, genera muy poca carga academica. Lo unico es que es bastante estricto con los formatos de entrega, pero con revisar bien, ok'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a7492b2ad7464c9699bf34d4b6357979098a4936d1489d9aa783d139387d25e8'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor y gran persona. Brinda mucho apoyo, se le puede consultar al terminar la clase o por WhatsApp. El curso son 10 tareas basadas en lo visto en clase, y como graba las sesiones, sirven de guía para hacerlas. Penaliza bastante si haces algo no visto en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-19T00:00:00+00:00'::TIMESTAMPTZ, '031e61fa8c1126ec6d92a6d4fb5601d6045d32e122ebb78050d1ee0b2eae6954'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Serán 10 quices solamente, pero hay que estudiar bastante pues la materia es complicada, los quices son diferentes por estudiante y la IA no da las respuestas correctas, hay que estar al día porque sino pierde el curso super fácil'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2026-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'ecf761d2aad8182122b02bb0ca2f70006252c469baf0acf733467c58ee82aa6d'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Meta Algoritmos con Helo si puede. Helo cae muy bien, el curso es 100% virtual, sin exámenes ni proyectos, solo 10 tareas que se hacen en pareja y si le cuesta algo le puede preguntar al profe, usa WhatsApp. Solo que programe en Maxima similar a como lo hace él, se da cuenta si usa codigo de ia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2026-01-20T00:00:00+00:00'::TIMESTAMPTZ, '09e02c4be4c90781fca6ac9f1db62fe712eac071b82398e8d4d5d258b7684f22'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Una joya entre los profes de compu, explica muy claro y los documentos con los que presentan te dan una muy buena guia para hacer todo lo que pida en el curso. Manda muchas tareas pero son faciles de hacer y muy utiles. Eso si, ponga cuidado a las cosas que el dice que son importantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, '33fdb8b5552a3d87d9fc85e896814ebc9a296d8d2a0c3ed22d88801c48499360'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Matricule con él con toda confianza. Excelente profe, tareas van de acuerdo con lo visto en clase. Muy buena persona y se ve que domina mucho la materia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-27T00:00:00+00:00'::TIMESTAMPTZ, '5275eb49731960e5701120e8394e8a4daf8be7a09fdb2d95fe707a107373ffa9'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor, explica MUY bien. El curso son solo 10 tareas y trata de dejarlo 100% virtual aunque diga semipresencial. Se puede hacer todo con GPT, así que el aprendizaje depende del estudiante. Si quiere aprender, lea la materia y haga las tareas a con.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '8e6fc351cf4ffb7bfa4950096b9a89e4d9a55b05a2246327f270c0d091b1d5e1'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Muy buen profesor, aunque salga semipresencial siempre va a intentar volver el curso 100% virtual, el curso son solo 10 tareas, sencillas que son conforme a lo visto en clase y fáciles. Nada más cumplir con lo que pide. Uno de los mejores profesores sin duda alguna'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-05-30T00:00:00+00:00'::TIMESTAMPTZ, '02983e9fdc45483b294ea41b4eec36d646f9d86b04f544f0a6862a01d3ad06ae'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Excelente profe. Matricule con él sin ninguna duda. Explica bien, las evaluaciones son adecuadas a lo que se explicó. Muy buena persona.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-16T00:00:00+00:00'::TIMESTAMPTZ, '98d0be98c6ca29b7cb526823565566e30eeeb47382fcfd87f608523ec7bdb33f'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'El profesor domina mucho los temas y sus clases no son para nada aburridas. Es buena persona pero en cuanto a evaluar se refiere es bastante estricto. Si el programa tiene el más mínimo fallo le baja muchos puntos, hacerle un reclamo es prácticamente imposible. Pasarle es sencillo si entrega todo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Deja trabajos largos']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'bf61c884a2dfae4d128be379454e9f164ec0b33a48eaf3a232d3d1492a0f1a4c'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Excelente profe, explica muy bien y si uno estudia le va bien en los exámenes y en los trabajos. Si puede matricular con él, hágalo sin ninguna duda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-03T00:00:00+00:00'::TIMESTAMPTZ, '89572911779f9a00e7353a66e3233ea768d58aabe2f167ee3565c11a5e0f82fd'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Es un curso normalito, muy fácil de pasar con buena nota. Aprende cosas vacilonas, pero tiende a simplificar mucho el algoritmo pues se abusa de los scripts que comparte el profe. Los quices son fáciles. Es un curso ñeh la verdad.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'ad965c8fd492b1f8e6dbbca99e81108affc9ffcd7bfea1d23c3562bbd23b4853'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Se enoja si le hace un reclamo, baja puntos sin sentido por cosas que no están en la instrucción, al menos durante las clases explica claro y no es difícil pasar.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-07T00:00:00+00:00'::TIMESTAMPTZ, 'cdee8971cde9fcd0598fe894e242c1e68079bc829e8a7f9cfd9d846dae46a4b8'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Excelente profe. Super ordenado y expone muy bien la materia. Si puede llevar un curso con él, adelante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-09-25T00:00:00+00:00'::TIMESTAMPTZ, '4edf7aef6380a6d0cd5d8da056f0b1f45911bb12362c99234048f6837680c5fc'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Qué dicha que por fin me encontré un profesor super bueno. Ya estaba cansado de otros profesores que hay por ahí. Super recomendado. Si puede matricular con él hágalo de inmediato.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-07-12T00:00:00+00:00'::TIMESTAMPTZ, '8d32d335b024b7ab4f9e7f409310820dfd146e8ee8e708503225a2c236dc24a8'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'El legendario e iniguable Don Helo, el mejor o sino uno de los mejores profesores que usted puede matricular. Ni lo piense dos veces si puede matricular con el, lleguele.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '6fffb6c8b0de683150a332981d494c4da9a316a3b883b87ae2dfb38db35a1fad'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Un profe super buena nota,, se preocupa porque todos entiendan, super ordenado, y hace la clase muy amena. De los mejores profes de Computacion. Si es verdad que deja unas tareas, pero son solo 10 y salen en menos de unas horas! Super recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-02T00:00:00+00:00'::TIMESTAMPTZ, 'd66e7e6be241e8c50b110d01ce3a30c1eff6984d565fa5132a4283dd602d86e7'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'El profesor deja 10 tareas, de ellas el promedio de las notas es su nota final. El curso se pasa individual o en grupo, haga las cosas con tiempo y entienda bien la materia. Esta vez el curso fue 100% virtual a pesar de ser semi presencial, es un amor de persona parece papá con carisma excepcional.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'd195160c540b974e812a52348a67f52f36d09748374673b65459ea5de1b2e066'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Si tiene la oportunidad de matricular con el hágalo sin pensarlo, explica muy claro, las clases son entretenidas y graciosas, ademas las evaluaciones son simples. La verdad tqm Helo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '0fee3090c7959d525dd9c8a022c9f506aa73194a88066cfe690cedb6c9cc1df1'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Clases súper pesadas. El curso es semi y hace todo virtual. Las clases se basan en leer su libro y en ejercicios muy repetitivos. El contenido del curso está, mas no tiene valor: solo le importa que hagan los quices que ya tiene listos de semestres pasados y no le da valor profesional al curso.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '1bff5b2a8655e90aa207f59d2e3b6b576a7fe20ddd255661459ec7711bfb181d'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'no sé qué más quieren de un profesor. es fácil, se aprende y cae bien. No se complica con las evaluaciones, es una tarea que se hace en 1h cada 2-3 semanas, y eso es 100% del curso. simplemente el mejor profe de progra por mucho, no hay competencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '5cb6e66650c37db726fd374d31e99a39daa32b9c3899d402c748336c68e99231'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Demasiado bueno. volvería a llevar otro curso con él. Qué lástima que no hay más profesores como él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9199f9a3b7042716c0257ee64a859b14d4090b0773524a5a3d908b05df51a359'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor, explicaciones claras y responde todas sus dudas. Por lo general las evaluaciones se basan en tareas bastante faciles de realizar. Si puede matricular con el hagalo!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ec64e4d5092bc39b715bc43a9bd1b28e33d04851f1cb2986b04e89a78529922b'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Un excelente profesor, cómico y carismático, explica muy bien los temas y el curso se pasa sólo con 10 tareas las cuales son bastante fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5217a8cb316e3aa75fa570b55c025870ceb114de3daff9e63785fff8225e1825'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Es muy buen profe, solo deja 10 quices en todo el semestre. Con estudiar lo que se ve en clase se pasa facilmente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'fe129598386ad2eabba5a2ade249d47e0864d25cbfd7ee9926571e5907cecb3f'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profe. Explica super claro en las clases presenciales o virtuales. El curso era semipresencial. Super buen profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, '6369e8dd3736a991422e40191ab31574d32ed6a451b57fb8d48ebb65b056565e'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor, excelente ser humano. De verdad es un gusto llevar un curso con él, es demasiado buena nota con los estudiantes, cómico y se esfuerza en dar la materia. Llevaría otra vez con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2023-05-31T00:00:00+00:00'::TIMESTAMPTZ, '6335a9169c67d5b7d1120a117b0032066eed986aaae1474549704e3a961fb67e'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'El mejor profesor que tiene la escuela de computación, se nota que le gusta la materia. Explica demasiado bien y deja pocas tareas. Siempre tiene la disposición de explicar algun tema que no se haya entendido antes. Es una persona increíble.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-12-22T00:00:00+00:00'::TIMESTAMPTZ, '328fa66261981947c24697f45e453682d4d8c2dde060b15d6371c7669bbef22a'::TEXT, ARRAY[1035]::BIGINT[]),
    (316::BIGINT, 'Explica muy bien, se ve que disfruta dar las clases. Solo hace 10 quices que son bastante fáciles, el curso se pasa muy fácilmente y sí se aprende.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-12-04T00:00:00+00:00'::TIMESTAMPTZ, '95093678bd4f53d4896ee433fc4d85c4a8ba7bdc44964cac426a58206d5473c2'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Un profe super bueno. Explica todo muy bien. Se entiende bien lo que explica. Se ve que disfruta dando clases. Super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2022-07-08T00:00:00+00:00'::TIMESTAMPTZ, '648e6abb15831d7d122f26a0c34db2e5120207d0b355ca4c20551b3ee1e5a950'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Es un amor de profe, la materia es muy interesante y él se esmera por enseñar. Explica detalles de los procesos para que se entienda porque X cosa sucede. Sin ninguna duda es de los mejores profes que tiene la carera. Hace 10 quices (10%), que si se estudia pueden ser faciles.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a8b190228f9613e395a03181066228f4e74ffb2dc01215564baa565a4d510cf1'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Este profesor literal alegraba mi semana jaja de los mejores profes de la escuela de compu, se preocupa por que los estudiantes entiendan bien, explica todo súper claro con muchísima paciencia y siempre trata de sacar una risa. Conoce mucho del tema y sabe transmitir ese conocimiento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1a02e5587ede71c55c5ebe012e91d02fcea818edcbce771ddf87bbccba912d48'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profe, explica super bien y las veces que sea necesario para que quede claro, se preocupa por que entendamos y por crear un ambiente bonito de clases, llevaría todos los cursos de la carrera con él de ser posible'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, '58d50cc44b5e1299855cfdd60aa378db8040753b7bf59bd85f9c3ad23f6c4ddb'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Que dicha que todavía hay profes tan buenos como Helo. Un profe que se ve que le gusta enseñar. Excelentes explicaciones (virtuales o presenciales). Conoce la materia y la evalúa muy bien. Se aprende demasiado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-03-22T00:00:00+00:00'::TIMESTAMPTZ, '15aa25756a63922190a063c88ddca9a20f8d2db652b8dd953633d0145e77cc54'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El profe explica bastante bien y en clase siempre está dispuesto a ayudar. Hace 10 quices, cada uno de 10% y esa es toda la nota. Es muy buena opción para llevar el curso. Lo único que puede ser malo es que no graba toda la clase y puede que deje cosas por fuera.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'c4f4bd719f0a1a01724031be28c2396c5f569f8224b2752b0260718300ff10d3'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Demasiado buena nota, sus explicaciones son sencillas. Los quices son fáciles si se lleva la materia al día.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'a1f9746aaab5bd72d7f27c6da83cfdcc16907345a7e038b6d8deb05382bfbffc'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor. En las clases presenciales era buenísimo, ahora que hay clases virtuales no todos pueden adaptarse, pero él sigue dando clases increíbles.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-06-07T00:00:00+00:00'::TIMESTAMPTZ, '058f5ba8a1e8b59f81ba6e93138adfd31016b1c123dbe6a8c933e85703b82d20'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Literal es un escape de los demás cursos. No siento que sea un profe que merezca 10 de calcification aquí. Es buen profe pero la gente lo adula demasiado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '21b00c5855763f18dd208e669bca362c6c8b6bec457393327837f95e532af806'::TEXT, ARRAY[1156]::BIGINT[]),
    (316::BIGINT, 'Simplemente un dios de dioses, una maravilla de curso, las "tareas" son ensayos muy pequeños que no quitan más de 30 min de una tarde, se aprende demasiado en las clases, se centra en explicarnos en grupos de charlas descubrimientos de nuestra era, entre otros temas. Era lo mejor de la semana'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'f072005795cce0a15fc063a67fe45d8d987302c239d92a9289bbb4c9d242bd1c'::TEXT, ARRAY[1156]::BIGINT[]),
    (316::BIGINT, 'Si existe una razón para sacar la carrera, es pasar por este curso con este profesor, excelente curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'c52fef630ecf73296097af7a2be548dc0c0fd411c8ddeac8aff9e9636d4c3052'::TEXT, ARRAY[1156]::BIGINT[]),
    (316::BIGINT, 'De lo mejores profesores de la escuela de computación, ha sido de las mejores experiencias en cursos, entendimiento 10/10, se toma la paciencia de volver a explicar las veces que sea necesario. Los exámenes/quices dado que solo son de 10 a 12 en el semestre son super razonables y ama su trabajo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'fc3901ff94af52facd1f97a3c8ca12b50d0d7f9614c7f46d6d31af4f2e4bb4dd'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profesor de la Escuela de Computación, tiene mucho orden con respecto a todas las evaluaciones que realiza y da la materia muy clara. Si a usted se le complica el saca de su tiempo para ayudarle, de verdad demuestra que le gusta enseñar y se preocupa para el estudiante. Muy crack el profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '0aecdb5b9ba04f0f71231c87883194fb392c43c7c4f77185da438c8584912a2c'::TEXT, ARRAY[1151]::BIGINT[]),
