    (316::BIGINT, 'Sin duda el mejor profesor con el que llevé este primer semestre virtual. Se pudo adaptar con facilidad y no cambió la calidad de la clase. Había escuchado las leyendas de Helo pero este semestre las confirmé.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'a511975d7b499a9821f472608647dc8a5113fff3e615f2ab560e991ddb7d023a'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'De los mejores profes de la carrera, Helo es una persona que hace que den ganas de ir a clases aunque sean virtuales. Explica demasiado bien, es muy carismático y alegre. Los quices no son fáciles y son la única evaluación, por lo que valen mucho y hay que estudiar. Recomendadisimo!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'acbf799f78b76c48a30092c0050bc877f2f7ecc2096bb73f1cd28a69e9483916'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Muy buen curso. Materia difícil, pero sabe como explicarla para que uno lo entienda. Siempre está dispuesto a ayudar al estudiante.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'b485ceee962291c9902aed30267910c9588f89039637436553decc251ae1b735'::TEXT, ARRAY[1151]::BIGINT[]),
