    (316::BIGINT, 'Excelente profesor, muy divertido, lleva la clase preparada, práctico, ayuda a los estudiantes dándoles práctica y materiales, hace la clase muy llevadera, todo se le entiende súper bien. En resumen, profe top de la escuela, no hay que pensearlo dos veces. No tolera las faltas de respeto hacia él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2019-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'e7552801081dd555c0ce8810d01ca09cacdbe7e3fd6c968dbfa0f5716bdbeeec'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Es el mejor profesor de la Escuela de Computación . Todas las clases son divertidas y se aprende mucho .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'a242e674ca75afe0113e64d4d506bc21681bf1e994627099464bef19c82c7b35'::TEXT, ARRAY[1151]::BIGINT[]),
