    (316::BIGINT, 'Muy buen profesor. Explica muy bien. Sin embargo, un poco injusto para calificar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'c6782f60ba918301e3b45161485cb5d0180bd240255e878dbba18f21bb77a84c'::TEXT, ARRAY[1151]::BIGINT[]),
