    (316::BIGINT, 'ufff El mejor profe de compu. Es toda una inspiración recibir clases así. Sabe demasiado, explica bien y es muy respetuoso con los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes']::TEXT[], '2019-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'd8ba0fa463a10e2ea2705ea9c0154a561cb53ed603dfb7af35bd3d8363b59182'::TEXT, ARRAY[1151]::BIGINT[]),
