    (316::BIGINT, 'Algunas clases son un bostezo pero se aprende bastante. Los PDF que brinda contienen toda la materia necesaria para estudiar y los quices son fáciles. Es demasiado religioso y suele contar historias de la Biblia en cada clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2019-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'a8d0fbd66946f586e9b443aed6f056c039bfdc40d052136876bbf97bff84f70e'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Super buen curso. Se aprende demasiado, es buenísimo explicando y se ve que sabe mucho de la materia, pero explica muy bien no es de esos profes que se la quieren hechar que sabe mucho, sino que por el conocimiento que tiene, sabe lo que tiene que explicar'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2019-04-30T00:00:00+00:00'::TIMESTAMPTZ, '565acf29711f4c6ba7bebc6d86c2e34ec93918b7f66b10474e5e5d006dbbac2d'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'EL mejor profe de Computación ahora que se fue Carranza, es un verdadero Crack, las clases son muy entretenidas, uno aprende montones y No se pueden perder UN minuto en la vida de Helo, es un verdadero Personaje'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '654f98bb06b5442cc71fe5702263cbc94e02e820ce98dcdcf4bf39392be7804e'::TEXT, ARRAY[1020]::BIGINT[]),
    (316::BIGINT, 'Esta clase hizo que me volviera a gustar estar en computación. Un profe que sabe mucho, sabe explicar y sabe evaluar. Deberían haber más profes así.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2018-09-28T00:00:00+00:00'::TIMESTAMPTZ, '5c27f221009e0e897a534f8871e7c372f544201a67b8082289bd0f45c9a4c50a'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente docente con el cual se aprenderá para toda la vida. Tengo más de 12 años de haber recibido este curso y el impacto del profesor en mi carrera ha sido muy significativo y positivo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2018-09-13T00:00:00+00:00'::TIMESTAMPTZ, '9fe04040e832aec3e726630b88960dd97962d9c9c5cf98fa46e90e97208a4451'::TEXT, ARRAY[3022]::BIGINT[]),
    (316::BIGINT, 'Super buen profe!! Estuve muy contento llendo a clases todo el semestre. Sabe demasiado y explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '67152ef850786235119972613e23e10d26508673e43c7642113e20fd92413b1d'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profesor de Computación. Explica de una forma tan clara que hasta dan ganas de ir a la clase. Practica y practica hasta que usted entienda. La evaluación se basa en un quiz semanal. Si usted le pone atención y practica un día antes, va a pasar y a aprender. Ojala todos fueran como Helo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a6e3842382bbfc00a4920aee78b756e168ceaaa32f8cf412c5b23bedf9799faf'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Por mucho el mejor profesor para impartir esa materia. Nada más hay que tener cuidado de no perder puntos tontos en los quices, porque califica bastante duro, pero la materia es super fácil y entendible con él. Hace un descanso para contarnos historias muy buenas. Vale mucho la pena llevar con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'bab05dbad1d4df6fcd95e5fe6668e61cc3a88020324ab0480533bcc0403879d9'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'EL profe sabe demasiado de IO, es super claro explicando y muy buen profesor. Sin embargo si usted se ofende facilmente no meta con él; como persona deja mucho que desear. Asistencia obligatoria y el curso es basicamente quiz cada semana y ya.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2679eb2057fdd841d07ff23a9d5ff9eb00568b3978f4342a5a337a52d7c8d369'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Es un crack. Sabe infinidad de investigación de operaciones, contesta todas las dudas. Ojo que el curso son sólo 11 quices-tareas (y ya), no hay que descuidar puntos. P.D: Si es muy religioso o se ve fácilmente ofendido, no lo lleve con él :v'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '41eb9430101728b04eadde48e5b61c003c89928638e4274669e671f5419a53d4'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Muy buen profesor, domina al 100% la materia y brinda todo el material teórico y ejemplos. Hay que tener cuidado con las ausencias, por el resto es muy buen curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4a37f0b3dfe0129c0c9cdbb7e364fd66287842a2609aa58a6ecf255aed435c69'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor. El mejor del tec simplemente! Las clases son muy entretenidas, el profesor da a los alumnos los apuntes de la materia, no hay donde perderse.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2018-04-06T00:00:00+00:00'::TIMESTAMPTZ, 'c95746726b5ce6d8305dfc5ba24afbf69964e42540e0cbd57fb5c3fc3dc07cf2'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Como profesor es excelente. Explica claro, atiende dudas y además sube la materia. Los quices son fáciles pero es fácil equivocarse'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-01T00:00:00+00:00'::TIMESTAMPTZ, '98ba61689c0f912887f4ac1f8a2cf77918eb3f7424009c2a533d8af1d8e12f08'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente el profe. domina la materia completamente y sabe muy bien como transmitirla.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f7c1616d9d755de6b6949720a621206bb7e09ee2280c1717812e463a0ed3d8a1'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Baja puntos, esperando que el estudiante reclame para retarle a quejarse. Quiere que todo se resuelva exactamente igual a como él lo resolvería.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2017-09-06T00:00:00+00:00'::TIMESTAMPTZ, '4cfc3016fd134b3807b585105fe5622fb88456b82abba4473d24ae2e417afbe5'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profe del TEC. Explica super bien, tiene todos los apuntes de las clases y las evaluaciones muy bien estructuradas. Ojalá hubiera más profes como él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f2d5bf58f765321bec960123a848a74fa89d4016ecdde724d3a205696f8f35fd'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profesor que tiene el TEC. No se gradue sin haber llevado mínimo un curso con este profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'fe5681310769e05c0d88ac572483e0a145c9d4ec0541a647b865754f70909497'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'De lo mejores profesores con los que he llevado, sabe mucho sobre cualquier tema. Son de los profes con los que hay que llevar al menos una vez durante la carrera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '36cbedced61cf6673d9e2e2db940112cb98823006e91ef799faf4b4681c4d23d'::TEXT, ARRAY[1156]::BIGINT[]),
    (316::BIGINT, 'De los mejores profesores que he tenido. La cantidad de conocimiento que tiene es irreal. Sin duda lo recomiendo para lo que sea. No hay que perderse la oportunidad de llevar algo con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '6be3994fe41bb15023722dbb69b2fc0e355c45d7efa1bb4a43718d900c6a99a9'::TEXT, ARRAY[1156]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor, me encanta la forma en que evalúa la clase. Helo esta "loco" pero eso lo hace ser un gran profesor. :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'ca6a8c651584dc693255703c91c8deed6f02219d361155ff9766de01575661eb'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Que super profe! Hacen falta más profesores con ese nivel. Muy bueno, explica super bien, super organizado el curso. Se ve que enseñar es su vocación.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'b82350a70b5a0611726d4847207d3a54821dd0943923750c531e0e86b4365bdf'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'De los mejores profesores de la escuela. Los apuntes son super claros en caso de que se tenga que faltar a una clase y todo el curso está muy bien organizado'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-10T00:00:00+00:00'::TIMESTAMPTZ, '2900219881082cbd70a3721a5564cef4f70e1ef720ddf1b419ac6b0f0a90ac9f'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profesor de la carrera! Apuntes de clases, exámenes bien programados de acuerdo a la materia vista en clase. Conoce muy bien la materia y es muy claro para explicar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'df57d811578dfe6d04e0fd6308660017c2326b14633b2045f93d99c8085f87c7'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Helo es excelente profesor. Explica increíblemente bien y hace que uno aprenda sin necesidad de saturarlo con trabajos. Tiene preparados los apuntes de todas las clases, así que con solo ir a poner atención y repasar se puede pasar con 100'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-10-21T00:00:00+00:00'::TIMESTAMPTZ, '470c600a90ffe81b7b4fe412eb11335c616c4863884b8cf585b07b530f0446ec'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor! Poniendo atención prácticamente todo queda claro. La evaluación es por quices y tareas (no hay exámenes ni proyectos). Las clases difícilmente se tornan aburridas pues el profesor es muy cómico. El profesor es ateo y lo expresa pero siempre con humor; no hay que ofenderse.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, '26d4a695824464d346d36d70aece8755eaf5cf1c8cb1446eaeb2b93376f78f08'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Hello tiene mi alma! a él le debo mi exitencia!! oh Gran Hello! lleva a todas las almas por el camino recto...de la sabiduría. jajaja! en fin!! es el mejor profe de la Escuela de Computación!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '8fcdbe82516fef1d04f39e77c5249a5cc8260d2d98ac084ce01e296d613314ad'::TEXT, ARRAY[1132]::BIGINT[]),
    (316::BIGINT, 'De los mejores profes que he tenido en la carrera. Se preocupa porque los estudiantes comprendan los temas y los apuntes son un éxito. Y de paso, los minutos en la vida de Helo son vacilones y crueles. No se puede salir del TEC sin llevar un curso con Helo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'b7fb4af8760afd6a90b7a3ba6c085bdc71be74a826e942b30d2c695980547c9e'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Tal vez para el que esté llevando dos cursos con él o que haya llevado algún curso anteriormente con él no sea muy divertido (el minuto en la vida de Helo se repite). Pero sigue demostrando ser uno de los mejores profesores de Computación.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '97f5ccb82d6d43f008fd6ed0b8374e1582141ef42990bfbfdbb2b9c28f711342'::TEXT, ARRAY[1132]::BIGINT[]),
    (316::BIGINT, 'Es un excelente profesor, el curso es fácil, toda la evaluación es por quices que son bastante sencillos, si se pone atención en clases,'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '76f82b1c99fb75f22bf5b50d52c25f1799c1f420a752badab14f49af193218bc'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Que profe más bueno. Da la materia perfecta y nos brinda sus apuntes. Super recomendado. Un ejemplo para los demás profes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-29T00:00:00+00:00'::TIMESTAMPTZ, 'f01a6afe2d26eb6fb0a450c6ea9e2943cac34ad02fb088b8b1bfff1f8695c42b'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profe de computación, aunque ya no vaya por los rumbos de la programación. Él sabe lo que habla, sabe mantener la atención de todos y lo mejor, es divertido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-02-03T00:00:00+00:00'::TIMESTAMPTZ, '16413a98cbf26b85db8d22fac8a15e00c1d00338a6b46dec3bab2b3995d627eb'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor, explica todo paso a paso sin omitir detalles. Las clases son vacilonas, en especial por "El minuto en la vida de Helo". El curso se pasa solo con quices (inclusive algunos para la casa).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, '0ed757730e9c3a651227332e071c4d5ea3e3de270f1e3b638740d7bbd281600d'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'No se pueden perder "Un minuto en la vida de Helo". Son las historias que lo mantienen vivo en el semestre'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-28T00:00:00+00:00'::TIMESTAMPTZ, '0167c53e243eed4ff6e7e51ad7f44aac014b44d14afa267fdcb487171e7170a1'::TEXT, ARRAY[3003]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor, no se limita a dar la materia, sino a nutrirla con datos de mucho interés, y además a despejar la mente con algunas anécdotas divertidas. Muy ordenado y no se invierte mucho tiempo en pasar la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-17T00:00:00+00:00'::TIMESTAMPTZ, 'fb9d4399b52769054ce9aa98532eb092d4b378ce144b90f5fe178342706911fe'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Definitivamente es un profesor con vocación. Sabe lo que hace, explica muy bien, y además brinda buenas fuentes de información. Las evaluaciones resultan fáciles con tan solo estudiar las notas que él facilita. Recomendado :)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-29T00:00:00+00:00'::TIMESTAMPTZ, 'c2f68f4677e308a829de75c00c5dcf2497600ce5613fae1cbe7991a9a496ee83'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Muy buen profesor. Explica todo con claridad y los ejercicios de los apuntes ayudan mucho para los quices. Aunque no estoy de acuerdo en algunas las las cosas que dice en sus anecdotas, pero su metodología es muy efectiva. Recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7441987147aa61fcfde4c461c520864a4d6e239f6fe9ba2e0304021e65607207'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c1b95139d6099c8812dcc4ae1f1c85e6e3a106b51655e0bac31f89088386cf08'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profe, pero sus anecdotas dejan otra impresion como persona lol'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'f67923b389507b9336fe8a48c348f0267c1c201c9c4e87ebba9ccf3b5dc67431'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente el profe. Sabe bien la materia, prepara mucho las clases, y hace evaluaciones muy justas. Una lástima que ahora de unas clases en Barrio Amón, en lugar de estar en Cartago. La verdad, se han ido muchos profes buenos de Cartago.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-06T00:00:00+00:00'::TIMESTAMPTZ, '2b5b7389efadddf0581819d01ecae6cd70974ba3d5ab0581d9a5a4f250855b34'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Increible el profe. Sabe mucho, explica super bien y si estudias te va a ir bien en las evaluaciones.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-01T00:00:00+00:00'::TIMESTAMPTZ, '1084857371684d2b43a37135ea78d587a108d678837088b643646bc101c0854d'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profesor! Explica muy bien! Las evaluaciones van acorde a la materia. Se ve que sabe mucho del tema.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-15T00:00:00+00:00'::TIMESTAMPTZ, '6d059920454e0a9df8afa73e89db4ca265a4226e86740ed23d1fc27461c9ea9f'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profe de toda la carrera de compu. Las clases estuvieron buenísimas. Por fin aprendí para que sirve toda la mate que lleva uno en los primeros años.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-15T00:00:00+00:00'::TIMESTAMPTZ, 'dd701b7aaf623c3d418b80da7ef94d9e1b8641b5463a4d90d68465e8fd6ef0ae'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'El mejor profesor de la Escuela de Computación. Tiene todo el material preparado. Se ve que conoce muy bien lo que enseña, pero lo explica con mucha claridad. Además el curso es muy interesante.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-04-15T00:00:00+00:00'::TIMESTAMPTZ, '12345ce00b7c0dc227d31f17fb5b3f4a18ed9ed6f663d616def94153b44ca92b'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Muy Buen profesor, lo mejor es el Minuto en la vida de Helo, con solo ir a clases y repasar antes del quiz se pasa el curso, no por facil, es porque da la materia muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '647cf2296e98370cd667f4ff32438ac019d633ca0b7738b561cf82b353b0fa90'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Excelente profe el mejor que he tenido hasta el momento, tuanis, explica demasiado bien y de paso da los apuntes de la materia para que uno solo llegue a prestar atención a clases, clases nada aburridas y hasta cuenta historias y chistes, altamente recomentado, con estudiar se pasa y sobrado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '13101341371e4a4e0a04cfc05edbce07484e0ce76b8ecd9139d35f119624355c'::TEXT, ARRAY[1151]::BIGINT[]),
    (316::BIGINT, 'Se pasa con las explicaciones, podría dar más materia, pero lo que da lo explica con un detalle increíble'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '25baa745cfe1263a001e1cdd9d3694ce06d98b1776c1571f969a66a862783966'::TEXT, ARRAY[1151]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
